INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002e5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss science and society at B2","Use Wissenschaft und Gesellschaft vocabulary","Talk about science policy, research funding, and Germany''s scientific culture"],"explanation":{"intro":"Science and society vocabulary covers science policy, research funding, and Germany''s place in global science at B2.","culturalNote":"Wissenschaft und Gesellschaft: Germany: DFG (Deutsche Forschungsgemeinschaft — national science fund), Max-Planck-Gesellschaft (basic research — 86 institutes), Fraunhofer (applied research — 76 institutes), Helmholtz (large-scale research — 18 centres), Leibniz Association. Key: Exzellenzinitiative (Excellence Initiative — 2006 — differentiated German universities — cluster funding). ''Humboldtian ideal'': Einheit von Forschung und Lehre (unity of research and teaching). Key metric: Germany #3 in scientific publications (after USA, China). Nobel Prize count: 108 total (physics, chemistry, medicine). Key concept: Wissensgesellschaft (knowledge society). Grundlagenforschung (basic research — no immediate application) vs. angewandte Forschung (applied research). Brain drain vs. brain gain. Science as public good. Responsible Research and Innovation (RRI — EU framework)."},"examples":[{"german":"Wissenschaft ist kein gesellschaftlich neutrales Unternehmen: Forschungsprioritäten werden durch Förderpolitik gesteuert, Erkenntnisse durch Interessen instrumentalisiert, und die Relevanz wissenschaftlicher Fragen wird durch gesellschaftliche Problemwahrnehmungen mitgeprägt. Die Humboldtsche Idee der zweckfreien Forschung steht in Spannung zu einer Wissenschaftspolitik, die Investitionen durch ökonomischen oder gesellschaftlichen Nutzen rechtfertigt.","english":"Science is not a socially neutral enterprise: research priorities are steered by funding policy, findings are instrumentalised by interests, and the relevance of scientific questions is co-shaped by societal problem perceptions. The Humboldtian idea of purpose-free research stands in tension with a science policy that justifies investments through economic or societal benefit."},{"german":"Deutschland verfügt über eine ausdifferenzierte Forschungsinfrastruktur: Während Universitäten das Humboldtsche Ideal der Einheit von Forschung und Lehre verkörpern, spezialisieren sich Max-Planck-Institute auf Grundlagenforschung, Fraunhofer-Institute auf Anwendungsforschung und Helmholtz-Zentren auf Großforschungsanlagen — eine institutionelle Arbeitsteilung, die internationale Wettbewerbsfähigkeit ermöglicht, aber auch Koordinierungsprobleme erzeugt.","english":"Germany has a differentiated research infrastructure: while universities embody the Humboldtian ideal of the unity of research and teaching, Max Planck Institutes specialise in basic research, Fraunhofer Institutes in applied research, and Helmholtz Centres in large-scale research facilities — an institutional division of labour that enables international competitiveness, but also creates coordination problems."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s research infrastructure, science policy, and Humboldtian ideals at B2."}}',
'{"items":[{"word":"ausdifferenziert","translation":"differentiated","pronunciation":"OWS-dif-feh-rent-zeert","example":"Ausdifferenzierte Infrastruktur."},{"word":"die Grundlagenforschung","translation":"basic research","pronunciation":"dee GROOND-lah-gen-for-shoong","example":"Reine Grundlagenforschung."},{"word":"verkörpern","translation":"to embody","pronunciation":"fer-KER-pern","example":"Ideale verkörpern."},{"word":"die Arbeitsteilung","translation":"division of labour","pronunciation":"dee AR-byts-ty-loong","example":"Institutionelle Arbeitsteilung."},{"word":"zweckfrei","translation":"purpose-free","pronunciation":"TSVEK-fry","example":"Zweckfreie Forschung."},{"word":"instrumentalisieren","translation":"to instrumentalise","pronunciation":"in-stru-men-tah-li-ZEE-ren","example":"Erkenntnisse instrumentalisieren."}]}',
'{"title":"In Spannung stehen zu X — to stand in tension with X","pattern":"X steht in Spannung zu Y = X stands in tension with Y (in Spannung stehen zu = to be in tension with — marks two things that are structurally incompatible or pull against each other without outright contradiction)","explanation":"In Spannung stehen zu = to stand in tension with. The phrase marks an unresolved structural conflict between two things: they coexist but pull in opposite directions. Die Humboldtsche Idee steht in Spannung zu einer Wissenschaftspolitik = the Humboldtian idea stands in tension with a science policy. The tension is not a direct contradiction (both can be true) but a structural incompatibility. Compare: im Widerspruch stehen zu (to contradict — stronger, implies logical incompatibility), unvereinbar sein mit (to be incompatible with — full incompatibility), sich reibungslos verbinden mit (to combine smoothly with — absence of tension), in einem Spannungsverhältnis stehen (in a relationship of tension — more elaborate version).","examples":[{"sentence":"Transparenz steht in Spannung zu Datenschutz.","translation":"Transparency stands in tension with data protection."},{"sentence":"Wirtschaftlichkeit steht in Spannung zu Nachhaltigkeit.","translation":"Economic efficiency stands in tension with sustainability."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Zweckfrei'' means?","options":["purpose-free","neutral","value-free","uncommitted"],"correctAnswer":"purpose-free"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Science is not a socially neutral enterprise: research priorities are steered by funding policy, findings are instrumentalised by interests, and the relevance of scientific questions is co-shaped by societal problem perceptions. The Humboldtian idea of purpose-free research stands in tension with a science policy that justifies investments through economic or societal benefit.","options":["Wissenschaft ist kein gesellschaftlich neutrales Unternehmen: Forschungsprioritäten werden durch Förderpolitik gesteuert, Erkenntnisse durch Interessen instrumentalisiert, und die Relevanz wissenschaftlicher Fragen wird durch gesellschaftliche Problemwahrnehmungen mitgeprägt. Die Humboldtsche Idee der zweckfreien Forschung steht in Spannung zu einer Wissenschaftspolitik, die Investitionen durch ökonomischen oder gesellschaftlichen Nutzen rechtfertigt.","Wissenschaft ist politisch, weil Forschungsgelder nicht neutral vergeben werden.","Das Humboldtsche Ideal der freien Forschung wird durch Nutzenorientierung bedroht.","Wissenschaftspolitik und Humboldtideal verfolgen gegensätzliche Ziele."],"correctAnswer":"Wissenschaft ist kein gesellschaftlich neutrales Unternehmen: Forschungsprioritäten werden durch Förderpolitik gesteuert, Erkenntnisse durch Interessen instrumentalisiert, und die Relevanz wissenschaftlicher Fragen wird durch gesellschaftliche Problemwahrnehmungen mitgeprägt. Die Humboldtsche Idee der zweckfreien Forschung steht in Spannung zu einer Wissenschaftspolitik, die Investitionen durch ökonomischen oder gesellschaftlichen Nutzen rechtfertigt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Transparenz steht in Spannung zu ___.","options":["Datenschutz","Sicherheit","Freiheit","Recht"],"correctAnswer":"Datenschutz"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Economic efficiency stands in tension with sustainability","wordBankItems":["Wirtschaftlichkeit","steht","in","Spannung","zu","Nachhaltigkeit","."],"correctAnswer":"Wirtschaftlichkeit steht in Spannung zu Nachhaltigkeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ausdifferenziert'' means?","options":["differentiated","diversified","specialised","developed"],"correctAnswer":"differentiated"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002e6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss academic freedom at B2","Use Wissenschaftsfreiheit vocabulary","Talk about Germany''s constitutionally protected academic freedom and its limits"],"explanation":{"intro":"Academic freedom vocabulary covers Germany''s constitutional protection of science, university autonomy, and the limits of academic freedom at B2.","culturalNote":"Wissenschaftsfreiheit: Germany: Grundgesetz Art. 5 Abs. 3 — ''Kunst und Wissenschaft, Forschung und Lehre sind frei'' — academic freedom constitutionally protected (since 1949). History: Deutsche Physik (Nazi era — Jewish physics rejected — Heisenberg vs. Lenard). Gleichschaltung (1933 — Nazi coordination of universities — 1,200 Jewish professors dismissed). Humboldt''s model: Lehr- und Forschungsfreiheit (freedom of teaching and research). Key tension: Wissenschaftsfreiheit vs. Forschungsfinanzierung (who funds? shapes agenda). Current debates: Cancel culture at universities — Meinungsfreiheit vs. Antidiskriminierung. Drittmittelabhängigkeit (third-party funding dependency — shapes research). Publish or perish. Science and the state: Sachverständigenrat (advisory councils — IPCC climate science — COVID scientific advisory). Key figure: Jürgen Habermas — discourse ethics, communicative rationality — academic freedom as precondition for rational discourse."},"examples":[{"german":"Wissenschaftsfreiheit ist kein schrankenloses Recht: Das Grundgesetz garantiert Forschungsfreiheit, setzt ihr aber durch andere Verfassungsgüter — Menschenwürde, Persönlichkeitsrechte, der Schutz vor Risikotechnologien — Grenzen. Dual-use-Forschung, Rüstungsforschung und Forschung mit gefährlichen Pathogenen zeigen, dass die Freiheit, zu forschen, und die Freiheit, die Ergebnisse zu veröffentlichen, ethisch getrennt bewertet werden müssen.","english":"Academic freedom is not an unlimited right: the Basic Law guarantees freedom of research, but limits it through other constitutional values — human dignity, personal rights, protection against risky technologies. Dual-use research, defence research, and research with dangerous pathogens show that the freedom to research and the freedom to publish results must be assessed ethically separately."},{"german":"Die Abhängigkeit der Universitäten von Drittmitteln schafft eine strukturelle Spannung mit der Wissenschaftsfreiheit: Wenn Forschungsagenden von Fördermittelgebern — Industrie, Stiftungen, staatlichen Forschungsprogrammen — abhängen, ist die formal garantierte Freiheit faktisch eingeschränkt. Nicht Zensur, sondern Anreizstrukturen formen die Wissenschaft.","english":"The dependency of universities on third-party funding creates a structural tension with academic freedom: when research agendas depend on funders — industry, foundations, state research programmes — the formally guaranteed freedom is factually constrained. Not censorship, but incentive structures shape science."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s constitutional academic freedom, its limits, and third-party funding tension at B2."}}',
'{"items":[{"word":"schrankenlos","translation":"unlimited/without restriction","pronunciation":"SHRAN-ken-lohs","example":"Schrankenloses Recht."},{"word":"das Verfassungsgut","translation":"constitutional value","pronunciation":"dahs fer-FAS-soongs-goot","example":"Andere Verfassungsgüter."},{"word":"der Dual-use","translation":"dual use","pronunciation":"DYOO-al yoos","example":"Dual-use-Forschung."},{"word":"der Drittmittel","translation":"third-party funding","pronunciation":"dayr DRIT-mi-tel","example":"Drittmittelabhängigkeit."},{"word":"faktisch","translation":"factually/in fact","pronunciation":"FAK-tish","example":"Faktisch eingeschränkt."},{"word":"der Anreiz","translation":"incentive","pronunciation":"dayr AN-ryts","example":"Anreizstrukturen."}]}',
'{"title":"Nicht X, sondern Y formen/gestalten Z — not X but Y shapes Z","pattern":"nicht X, sondern Y forme Z = not X, but Y shapes Z (nicht...sondern = not...but — corrects the expected explanation X and substitutes the actual cause Y; formen/gestalten = to shape, form)","explanation":"Nicht...sondern... = not...but... The pattern corrects a common assumption about causation: the expected cause (X = Zensur/censorship) is denied, and the actual cause (Y = Anreizstrukturen/incentive structures) is substituted. Nicht Zensur, sondern Anreizstrukturen formen die Wissenschaft = Not censorship, but incentive structures shape science. The pattern is powerful in critical analysis: it refuses the obvious villain (censorship, propaganda) and points to structural/systemic causes that are harder to see and resist. Compare: es liegt nicht an X sondern an Y (it lies not in X but in Y), nicht explizit, sondern implizit (not explicit, but implicit), nicht durch Verbote, sondern durch Anreize (not through prohibitions, but through incentives).","examples":[{"sentence":"Nicht Verbote, sondern Eigeninteressen formen die Politik.","translation":"Not prohibitions, but self-interests shape politics."},{"sentence":"Nicht Zwang, sondern Gewohnheit formt das Verhalten.","translation":"Not coercion, but habit shapes behaviour."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Schrankenlos'' means?","options":["unlimited/without restriction","unrestricted","boundless","unconstrained"],"correctAnswer":"unlimited/without restriction"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The dependency of universities on third-party funding creates a structural tension with academic freedom: when research agendas depend on funders — industry, foundations, state research programmes — the formally guaranteed freedom is factually constrained. Not censorship, but incentive structures shape science.","options":["Die Abhängigkeit der Universitäten von Drittmitteln schafft eine strukturelle Spannung mit der Wissenschaftsfreiheit: Wenn Forschungsagenden von Fördermittelgebern — Industrie, Stiftungen, staatlichen Forschungsprogrammen — abhängen, ist die formal garantierte Freiheit faktisch eingeschränkt. Nicht Zensur, sondern Anreizstrukturen formen die Wissenschaft.","Drittmittelabhängigkeit beschränkt Forschungsfreiheit stärker als staatliche Kontrolle.","Externe Finanzierung beeinflusst Forschungsthemen mehr als Zensur es je könnte.","Wissenschaftsfreiheit ist faktisch eingeschränkt, wenn Drittmittelgeber die Agenda bestimmen."],"correctAnswer":"Die Abhängigkeit der Universitäten von Drittmitteln schafft eine strukturelle Spannung mit der Wissenschaftsfreiheit: Wenn Forschungsagenden von Fördermittelgebern — Industrie, Stiftungen, staatlichen Forschungsprogrammen — abhängen, ist die formal garantierte Freiheit faktisch eingeschränkt. Nicht Zensur, sondern Anreizstrukturen formen die Wissenschaft."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nicht Verbote, sondern Eigeninteressen ___ die Politik.","options":["formen","gestalten","bestimmen","beeinflussen"],"correctAnswer":"formen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Not coercion but habit shapes behaviour","wordBankItems":["Nicht","Zwang",",","sondern","Gewohnheit","formt","das","Verhalten","."],"correctAnswer":"Nicht Zwang , sondern Gewohnheit formt das Verhalten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Faktisch'' means?","options":["factually/in fact","actually","in practice","effectively"],"correctAnswer":"factually/in fact"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002e7',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss research ethics at B2","Use Forschungsethik vocabulary","Talk about informed consent, animal testing, and bioethics in Germany"],"explanation":{"intro":"Research ethics vocabulary covers informed consent, bioethics, and Germany''s regulatory approach to research ethics at B2.","culturalNote":"Forschungsethik: Germany: Ethikkommissionen (ethics committees — mandatory review for human subject research — all German universities). Key: Nürnberger Kodex (1947 — first international research ethics code — informed consent — response to Nazi medical crimes). Helsinki Declaration (1964 — medical ethics). Informed consent (informierte Einwilligung). Animal experimentation (Tierversuche — Germany: 2.5 million animals/year — heavily regulated). Key issues: Stammzellenforschung (stem cell research — Stammzellgesetz 2002 — Germany: strict limits on embryonic stem cells). Gentherapie (gene therapy). CRISPR ethics. Data ethics (Algorithmic decision-making — GDPR). Dual-use (research that could be used as weapon). Research misconduct (Forschungsintegrität — Guttenberg plagiarism — Schavan plagiarism — doctorate fraud scandals). Deutsche Forschungsgemeinschaft (DFG) research integrity guidelines."},"examples":[{"german":"Forschungsethik verfolgt einen Doppelauftrag: Sie schützt Forschungssubjekte — Menschen, Tiere, Ökosysteme — vor Schäden durch Forschungshandlungen, und sie sichert die epistemische Integrität der Wissenschaft gegen Verzerrungen durch wirtschaftliche Interessen, politische Anforderungen oder wissenschaftliche Karrierelogik. Beide Funktionen sind voneinander abhängig: eine Wissenschaft, die ihre Probanden ausbeutet, verliert auch ihre Glaubwürdigkeit.","english":"Research ethics pursues a dual mandate: it protects research subjects — humans, animals, ecosystems — from harm by research actions, and it secures the epistemic integrity of science against distortions by economic interests, political requirements, or scientific career logic. Both functions are interdependent: a science that exploits its subjects also loses its credibility."},{"german":"Der Nürnberger Kodex ist das ethische Fundament moderner Forschungsethik: Als Reaktion auf die Humanexperimente der NS-Medizin formuliert er das Prinzip der informierten, freiwilligen Einwilligung als unverzichtbare Voraussetzung für medizinische Forschung am Menschen — ein Grundsatz, dessen universale Geltung durch Verletzungen in der Entwicklungsländerforschung wiederholt herausgefordert wird.","english":"The Nuremberg Code is the ethical foundation of modern research ethics: as a response to the human experiments of Nazi medicine, it formulates the principle of informed, voluntary consent as an indispensable prerequisite for medical research on humans — a principle whose universal validity is repeatedly challenged by violations in research in developing countries."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the Nuremberg Code, research ethics principles, and Germany''s bioethics at B2."}}',
'{"items":[{"word":"die Einwilligung","translation":"consent","pronunciation":"dee YN-vi-li-goong","example":"Informierte Einwilligung."},{"word":"epistemisch","translation":"epistemic","pronunciation":"eh-pis-TEH-mish","example":"Epistemische Integrität."},{"word":"die Verzerrung","translation":"distortion","pronunciation":"dee fer-TSER-roong","example":"Verzerrungen vermeiden."},{"word":"ausbeutet","translation":"to exploit","pronunciation":"OWS-boy-ten","example":"Probanden ausbeuten."},{"word":"unverzichtbar","translation":"indispensable","pronunciation":"oon-fer-TSIKHT-bar","example":"Unverzichtbare Voraussetzung."},{"word":"herausfordern","translation":"to challenge","pronunciation":"her-OWS-for-dern","example":"Grundsatz herausfordern."}]}',
'{"title":"Als Reaktion auf X formuliert Y das Prinzip von Z — as a response to X, Y formulates the principle of Z","pattern":"als Reaktion auf X formuliert Y das Prinzip/Grundsatz von Z = as a response to X, Y formulates the principle/principle of Z (als Reaktion auf = as a response to — marks historical genesis; formulieren = to formulate — marks a defining/codifying act)","explanation":"Als Reaktion auf X = as a response to X (als = as; Reaktion auf + accusative = reaction to X). Formulieren = to formulate (to define, codify — more deliberate than ''say'' or ''state''). Als Reaktion auf die NS-Humanexperimente formuliert der Kodex das Prinzip der informierten Einwilligung = As a response to the Nazi human experiments, the code formulates the principle of informed consent. The pattern places the moral/legal development in direct causal/responsive relationship to a prior harm. Widely used in ethics, law, and policy to explain the origin of norms. Compare: als Antwort auf (as an answer to — same structure, less formal), infolge von X (as a result of X — more causal than responsive), nach X wurde Y eingeführt (after X, Y was introduced — looser connection).","examples":[{"sentence":"Als Reaktion auf die Krise formulierte die EU neue Bankenregeln.","translation":"As a response to the crisis, the EU formulated new banking rules."},{"sentence":"Als Reaktion auf den Skandal führte das Unternehmen ein Compliance-System ein.","translation":"As a response to the scandal, the company introduced a compliance system."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Epistemisch'' means?","options":["epistemic","cognitive","scientific","theoretical"],"correctAnswer":"epistemic"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Nuremberg Code is the ethical foundation of modern research ethics: as a response to the human experiments of Nazi medicine, it formulates the principle of informed, voluntary consent as an indispensable prerequisite for medical research on humans — a principle whose universal validity is repeatedly challenged by violations in research in developing countries.","options":["Der Nürnberger Kodex ist das ethische Fundament moderner Forschungsethik: Als Reaktion auf die Humanexperimente der NS-Medizin formuliert er das Prinzip der informierten, freiwilligen Einwilligung als unverzichtbare Voraussetzung für medizinische Forschung am Menschen — ein Grundsatz, dessen universale Geltung durch Verletzungen in der Entwicklungsländerforschung wiederholt herausgefordert wird.","Der Nürnberger Kodex entstand nach den NS-Menschenversuchen und fordert informierte Einwilligung.","Informierte Einwilligung als Forschungsethik-Grundsatz gilt universell, wird aber oft verletzt.","Die Forschungsethik nach 1945 gründet auf dem Verbot von Humanversuchen ohne Einwilligung."],"correctAnswer":"Der Nürnberger Kodex ist das ethische Fundament moderner Forschungsethik: Als Reaktion auf die Humanexperimente der NS-Medizin formuliert er das Prinzip der informierten, freiwilligen Einwilligung als unverzichtbare Voraussetzung für medizinische Forschung am Menschen — ein Grundsatz, dessen universale Geltung durch Verletzungen in der Entwicklungsländerforschung wiederholt herausgefordert wird."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Als Reaktion auf die Krise formulierte die EU neue ___.","options":["Bankenregeln","Gesetze","Regeln","Bestimmungen"],"correctAnswer":"Bankenregeln"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: As a response to the scandal the company introduced a compliance system","wordBankItems":["Als","Reaktion","auf","den","Skandal","führte","das","Unternehmen","ein","Compliance-System","ein","."],"correctAnswer":"Als Reaktion auf den Skandal führte das Unternehmen ein Compliance-System ein ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unverzichtbar'' means?","options":["indispensable","essential","necessary","required"],"correctAnswer":"indispensable"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002e8',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss peer review and scientific culture at B2","Use Peer-Review und Wissenschaftskultur vocabulary","Talk about the replication crisis, peer review limitations, and German scientific culture"],"explanation":{"intro":"Peer review and scientific culture vocabulary covers replication crisis, publication bias, and scientific norms at B2.","culturalNote":"Peer Review und Wissenschaftskultur: Key: Peer Review (Begutachtungsverfahren) — cornerstone of quality assurance in science (anonymous expert review before publication). Replication crisis (Replikationskrise — 2011+ — psychology, medical sciences — many studies don''t replicate: Open Science Collaboration 2015: only 39 of 100 psychology studies replicated). Publication bias (Publikationsbias — only positive results published — file-drawer problem). P-hacking (manipulating statistical analysis to achieve p<0.05). Predatory journals (Raubverlage). Open peer review. Altmetrics. Retraction Watch (website tracking retractions — growing). Germany: Guttenberg Affair (2011 — doctorate plagiarism — Defence Minister resigned), Schavan (2013). Reproducibility as new scientific norm: reproducible science movement. Deutsche Forschungsgemeinschaft: Selbstverpflichtung zur wissenschaftlichen Integrität (self-commitment to scientific integrity)."},"examples":[{"german":"Die Replikationskrise hat eine unbequeme Wahrheit über wissenschaftliche Wissensproduktion freigelegt: Viele als gesichert geltende Befunde lassen sich unter gleichen Bedingungen nicht reproduzieren — ein Befund, der auf das Zusammenspiel von Publikationsbias, p-hacking und Stichprobengrößen hinweist. Die Krise erzwingt eine Reflexion über die epistemischen Standards, nach denen Erkenntnisse als wissenschaftlich valide gelten.","english":"The replication crisis has revealed an uncomfortable truth about scientific knowledge production: many findings considered established cannot be reproduced under identical conditions — a finding that points to the interaction of publication bias, p-hacking, and sample sizes. The crisis forces a reflection on the epistemic standards by which findings are considered scientifically valid."},{"german":"Peer Review ist ein unvollkommenes, aber unverzichtbares Instrument der Wissenschaftsqualität: Es filtert grobe Fehler, gewährleistet Mindeststandards fachlicher Kompetenz und verleiht Publikationen institutionellen Kredit — kann aber systemische Verzerrungen, paradigmatische Betriebsblindheit und die Unterdrückung innovativer Außenseiterpositionen nicht verhindern.","english":"Peer review is an imperfect but indispensable instrument of scientific quality: it filters out gross errors, ensures minimum standards of professional competence, and lends publications institutional credit — but cannot prevent systemic distortions, paradigmatic blind spots, and the suppression of innovative outsider positions."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the replication crisis, peer review limitations, and publication bias at B2."}}',
'{"items":[{"word":"reproduzieren","translation":"to reproduce","pronunciation":"reh-pro-doo-ZEE-ren","example":"Befunde reproduzieren."},{"word":"das Zusammenspiel","translation":"interaction/interplay","pronunciation":"dahs tsoo-ZA-men-shpeel","example":"Zusammenspiel von Faktoren."},{"word":"erzwingen","translation":"to force","pronunciation":"er-TSVING-en","example":"Reflexion erzwingen."},{"word":"unvollkommen","translation":"imperfect","pronunciation":"oon-FOL-ko-men","example":"Unvollkommenes Instrument."},{"word":"die Betriebsblindheit","translation":"blind spot (organisational)","pronunciation":"dee beh-TREEPS-blint-hyt","example":"Paradigmatische Betriebsblindheit."},{"word":"unterdrücken","translation":"to suppress","pronunciation":"oon-ter-DRÜ-ken","example":"Positionen unterdrücken."}]}',
'{"title":"Auf X hinweisen — to point to X (indicate, signal)","pattern":"auf X hinweisen = to point to X (hinweisen auf + accusative — draws attention to X as a significant factor, cause, or implication; separable: weist...hin)","explanation":"Hinweisen auf = to point to, indicate (hin = towards; weisen = to point, show — separable). Ein Befund, der auf X hinweist = a finding that points to X. Hinweisen auf is used when something (evidence, a finding, a sign) indicates or points toward a conclusion that isn''t directly stated but inferred. Compare: zeigen (to show — more direct and immediate), belegen (to demonstrate/prove — requires direct evidence), andeuten (to suggest — softer, more tentative), darauf hindeuten (to indicate/hint at — synonym, slightly softer than hinweisen auf). Weist auf X hin = points to X / indicates X (present tense, third person singular — hin at end).","examples":[{"sentence":"Die Daten weisen auf einen Zusammenhang hin.","translation":"The data points to a connection."},{"sentence":"Der Befund weist auf strukturelle Probleme hin.","translation":"The finding points to structural problems."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Erzwingen'' means?","options":["to force","to compel","to coerce","to impose"],"correctAnswer":"to force"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The replication crisis has revealed an uncomfortable truth about scientific knowledge production: many findings considered established cannot be reproduced under identical conditions — a finding that points to the interaction of publication bias, p-hacking, and sample sizes. The crisis forces a reflection on the epistemic standards by which findings are considered scientifically valid.","options":["Die Replikationskrise hat eine unbequeme Wahrheit über wissenschaftliche Wissensproduktion freigelegt: Viele als gesichert geltende Befunde lassen sich unter gleichen Bedingungen nicht reproduzieren — ein Befund, der auf das Zusammenspiel von Publikationsbias, p-hacking und Stichprobengrößen hinweist. Die Krise erzwingt eine Reflexion über die epistemischen Standards, nach denen Erkenntnisse als wissenschaftlich valide gelten.","Viele Studien können nicht reproduziert werden — das erschüttert das Vertrauen in die Wissenschaft.","Die Replikationskrise zeigt, dass Publikationsbias systematisch Erkenntnisse verzerrt.","Wissenschaftliche Befunde gelten erst dann als valide, wenn sie reproduzierbar sind."],"correctAnswer":"Die Replikationskrise hat eine unbequeme Wahrheit über wissenschaftliche Wissensproduktion freigelegt: Viele als gesichert geltende Befunde lassen sich unter gleichen Bedingungen nicht reproduzieren — ein Befund, der auf das Zusammenspiel von Publikationsbias, p-hacking und Stichprobengrößen hinweist. Die Krise erzwingt eine Reflexion über die epistemischen Standards, nach denen Erkenntnisse als wissenschaftlich valide gelten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Daten weisen auf einen Zusammenhang ___.","options":["hin","auf","an","vor"],"correctAnswer":"hin"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The finding points to structural problems","wordBankItems":["Der","Befund","weist","auf","strukturelle","Probleme","hin","."],"correctAnswer":"Der Befund weist auf strukturelle Probleme hin ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unterdrücken'' means?","options":["to suppress","to repress","to silence","to stifle"],"correctAnswer":"to suppress"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002e9',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss science communication at B2","Use Wissenschaftskommunikation vocabulary","Talk about science journalism, deficit model, and Germany''s science communication landscape"],"explanation":{"intro":"Science communication vocabulary covers deficit model, science journalism, and Germany''s public science engagement at B2.","culturalNote":"Wissenschaftskommunikation: Germany: Wissenschaft im Dialog (science in dialogue — national organisation for science communication). Key: Deficit model (Defizitmodell — public lacks knowledge → just give them the facts — now widely critiqued — replaced by dialogue model). Science journalism (Wissenschaftsjournalismus — decline: many science editors cut). Key institutions: Wissenschaftszentrum Berlin, Spektrum der Wissenschaft (German Scientific American). Science festivals: Lange Nacht der Wissenschaften (Berlin). Key debates: Climate change communication — framing. COVID misinformation — RKI communication criticism. Anti-vaccination debate. Science communication of uncertainty: ''we don''t know yet'' — how to say it without creating doubt. Complexity vs. simplification (Vereinfachung). Fact-checking. Social media and science: Twitter/X science communities. Citizen Science (Bürgerwissenschaft). Key tension: Popularisierung vs. Genauigkeit (popularisation vs. accuracy)."},"examples":[{"german":"Das Defizitmodell der Wissenschaftskommunikation geht von einer folgenschweren Fehlannahme aus: Es behandelt Skepsis gegenüber wissenschaftlichen Konsensen als Wissensdefizit, das durch Informationsbereitstellung behebbar ist — und übersieht, dass Wissenschaftsskepsis häufig wertbasiert ist, auf Misstrauen gegenüber Institutionen beruht oder aus konkreten Erfahrungen mit technologischen Risiken entsteht. Mehr Information allein erzeugt kein mehr Vertrauen.","english":"The deficit model of science communication starts from a consequential false assumption: it treats scepticism towards scientific consensus as a knowledge deficit that can be remedied by providing information — and overlooks that science scepticism is frequently value-based, rests on distrust of institutions, or arises from concrete experiences with technological risks. More information alone does not generate more trust."},{"german":"Wissenschaftskommunikation steht vor dem Paradox, Komplexität reduzieren zu müssen, ohne Unwahrheiten zu schaffen: Eine Vereinfachung, die Unsicherheiten verbirgt, stärkt zunächst das Vertrauen, hinterlässt aber erhöhte Skepsis, wenn die Öffentlichkeit später von den Korrekturen erfährt. Transparenz über wissenschaftliche Unsicherheit ist demokratisch geboten, auch wenn sie kurzfristig unbequem ist.","english":"Science communication faces the paradox of having to reduce complexity without creating untruths: a simplification that conceals uncertainties initially strengthens trust, but leaves behind heightened scepticism when the public later learns of the corrections. Transparency about scientific uncertainty is democratically required, even if it is uncomfortable in the short term."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the deficit model, science communication challenges, and trust paradoxes at B2."}}',
'{"items":[{"word":"folgenschwer","translation":"consequential","pronunciation":"FOL-gen-shver","example":"Folgenschwere Fehlannahme."},{"word":"die Fehlannahme","translation":"false assumption","pronunciation":"dee FAL-an-nah-meh","example":"Von einer Fehlannahme ausgehen."},{"word":"behebbar","translation":"remediable/fixable","pronunciation":"beh-HEB-bar","example":"Durch Information behebbar."},{"word":"wertbasiert","translation":"value-based","pronunciation":"VERT-ba-zeert","example":"Wertbasierte Skepsis."},{"word":"hinterlassen","translation":"to leave behind","pronunciation":"hin-ter-LAS-en","example":"Skepsis hinterlassen."},{"word":"geboten","translation":"required/called for","pronunciation":"geh-BOH-ten","example":"Demokratisch geboten."}]}',
'{"title":"Von einer Fehlannahme ausgehen — to start from a false assumption","pattern":"von einer Fehlannahme/falschen Annahme ausgehen = to start from a false assumption (ausgehen von + dative — marks the starting point or premise; Fehlannahme = erroneous assumption; the phrase introduces a critique by identifying a flawed premise)","explanation":"Ausgehen von = to start from, proceed from (ausgehen = separable: geht...aus; von + dative marks the starting point or premise — literally ''to go out from''). Von einer Fehlannahme ausgehen = to start from a false assumption. The phrase introduces a critical move: identifying that an argument, model, or policy rests on a flawed premise. Marks the diagnosis before the critique. Compare: auf einer falschen Annahme beruhen (to rest on a false assumption — more static), sich irren (to be wrong — simpler), eine falsche Prämisse haben (to have a false premise — more logical/formal), falsch liegen (to be wrong — colloquial).","examples":[{"sentence":"Diese Politik geht von der Fehlannahme aus, dass Bestrafung Verhalten ändert.","translation":"This policy starts from the false assumption that punishment changes behaviour."},{"sentence":"Das Modell geht von einer vereinfachenden Annahme über menschliches Verhalten aus.","translation":"The model starts from a simplifying assumption about human behaviour."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Folgenschwer'' means?","options":["consequential","serious","significant","grave"],"correctAnswer":"consequential"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The deficit model of science communication starts from a consequential false assumption: it treats scepticism towards scientific consensus as a knowledge deficit that can be remedied by providing information — and overlooks that science scepticism is frequently value-based, rests on distrust of institutions, or arises from concrete experiences with technological risks. More information alone does not generate more trust.","options":["Das Defizitmodell der Wissenschaftskommunikation geht von einer folgenschweren Fehlannahme aus: Es behandelt Skepsis gegenüber wissenschaftlichen Konsensen als Wissensdefizit, das durch Informationsbereitstellung behebbar ist — und übersieht, dass Wissenschaftsskepsis häufig wertbasiert ist, auf Misstrauen gegenüber Institutionen beruht oder aus konkreten Erfahrungen mit technologischen Risiken entsteht. Mehr Information allein erzeugt kein mehr Vertrauen.","Das Defizitmodell nimmt an, dass Unwissen der Grund für Wissenschaftsskepsis ist.","Wissenschaftsskepsis hat viele Ursachen — nicht nur mangelndes Wissen.","Mehr wissenschaftliche Information macht Menschen nicht automatisch aufgeschlossener."],"correctAnswer":"Das Defizitmodell der Wissenschaftskommunikation geht von einer folgenschweren Fehlannahme aus: Es behandelt Skepsis gegenüber wissenschaftlichen Konsensen als Wissensdefizit, das durch Informationsbereitstellung behebbar ist — und übersieht, dass Wissenschaftsskepsis häufig wertbasiert ist, auf Misstrauen gegenüber Institutionen beruht oder aus konkreten Erfahrungen mit technologischen Risiken entsteht. Mehr Information allein erzeugt kein mehr Vertrauen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Politik geht von der Fehlannahme aus, dass Bestrafung Verhalten ___.","options":["ändert","verändert","beeinflusst","steuert"],"correctAnswer":"ändert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The model starts from a simplifying assumption about human behaviour","wordBankItems":["Das","Modell","geht","von","einer","vereinfachenden","Annahme","über","menschliches","Verhalten","aus","."],"correctAnswer":"Das Modell geht von einer vereinfachenden Annahme über menschliches Verhalten aus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Geboten'' means?","options":["required/called for","necessary","obligatory","imperative"],"correctAnswer":"required/called for"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ea',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss pseudoscience and science scepticism at B2","Use Pseudowissenschaft und Wissenschaftsskepsis vocabulary","Talk about homeopathy, conspiracy theories, and scientific literacy in Germany"],"explanation":{"intro":"Pseudoscience and science scepticism vocabulary covers homeopathy, conspiracy theories, and scientific literacy at B2.","culturalNote":"Pseudowissenschaft und Wissenschaftsskepsis: Germany: Homöopathie (homeopathy — widely practiced — ~1,700 German homeopathic doctors — public health insurance covered until 2019 in some Kassen — major GMK debate). Anthroposophie (anthroposophy — Rudolf Steiner — Waldorf schools — controversial medical claims). Alternative Medizin controversy. Key: Wissenschaftliche Konsens vs. wissenschaftlicher Dissens (genuine vs. manufactured doubt). Climate denial tactics (Tobacco strategy — manufactured doubt — Merchants of Doubt — Oreskes and Conway). Verschwörungstheorien (conspiracy theories — COVID: Querdenker movement — 2020). Anti-Impfbewegung (anti-vaccination movement — measles re-emergence). Homöopathie-Debatte: Placebo-Effekt (placebo effect). Wissenschaftsskeptizismus (healthy scientific scepticism vs. pseudoscientific scepticism). Key: Abgrenzungsproblem (demarcation problem — Karl Popper — what is science? Falsifiability)."},"examples":[{"german":"Das Abgrenzungsproblem ist keine bloß akademische Frage: Die Grenze zwischen Wissenschaft und Pseudowissenschaft hat gesellschaftliche Konsequenzen — sie entscheidet, welche Erkenntnisse als Grundlage politischer Entscheidungen gelten, welche Therapien erstattungsfähig sind und welche epistemischen Autoritäten in öffentlichen Debatten Gehör finden. Poppers Falsifizierbarkeitskriterium liefert ein Instrument, reicht aber nicht aus, um die Trennlinie allein zu ziehen.","english":"The demarcation problem is not merely an academic question: the boundary between science and pseudoscience has social consequences — it decides which findings count as the basis for political decisions, which therapies are reimbursable, and which epistemic authorities find a hearing in public debates. Popper''s falsifiability criterion provides an instrument, but does not suffice to draw the dividing line alone."},{"german":"Verschwörungstheorien sind keine schlichte Folge mangelnder Bildung, sondern ein komplexes epistemisches Phänomen: Sie bieten Erklärungen für Kontingenz und Chaos, ermöglichen soziale Zugehörigkeit in Misstrauensgemeinschaften und sind gegen Widerlegung immunisiert — weil jeder Gegenbeleg als Beweis des Komplotts gilt. Diese epistemische Immunisierung macht sie besonders resistent gegenüber Aufklärungsstrategien.","english":"Conspiracy theories are not a simple consequence of lack of education, but a complex epistemic phenomenon: they offer explanations for contingency and chaos, enable social belonging in communities of distrust, and are immunised against refutation — because every counterevidence counts as proof of the conspiracy. This epistemic immunisation makes them particularly resistant to enlightenment strategies."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Popper''s demarcation problem, conspiracy theories, and pseudoscience at B2."}}',
'{"items":[{"word":"die Abgrenzung","translation":"demarcation","pronunciation":"dee AB-grents-oong","example":"Abgrenzungsproblem."},{"word":"erstattungsfähig","translation":"reimbursable","pronunciation":"er-SHTAT-oongs-fä-ikh","example":"Erstattungsfähige Therapie."},{"word":"die Falsifizierbarkeit","translation":"falsifiability","pronunciation":"dee fal-zi-fi-TSEER-bar-kyt","example":"Poppers Falsifizierbarkeitskriterium."},{"word":"die Kontingenz","translation":"contingency","pronunciation":"dee kon-tin-GENTS","example":"Erklärungen für Kontingenz."},{"word":"immunisiert","translation":"immunised","pronunciation":"i-moo-ni-ZEERT","example":"Gegen Widerlegung immunisiert."},{"word":"die Widerlegung","translation":"refutation","pronunciation":"dee VI-der-leh-goong","example":"Resistenz gegenüber Widerlegung."}]}',
'{"title":"Gegen X immunisiert sein — to be immunised against X (structurally resistant)","pattern":"gegen X immunisiert sein = to be immunised against X (immunisiert = immunised — passive participle used as predicate; gegen + accusative = against X; marks a structural resistance, not merely psychological — the phenomenon is so constructed that X (refutation, evidence) cannot penetrate it)","explanation":"Gegen X immunisiert = immunised against X. Immunisiert sein = to be immunised (immunisiert — past participle of immunisieren used as stative predicate). Gegen Widerlegung immunisiert = immunised against refutation. The phrase marks a structural feature, not a psychological stubbornness: the theory/system is constructed so that counter-evidence is reinterpreted as confirmatory. Widely used in epistemology (Lakatos: auxiliary hypotheses protect core), political science (populism — all counterevidence dismissed as ''establishment''), and psychology. Compare: resistent gegenüber (resistant to — more general), unangreifbar sein (to be unassailable — more positive), nicht falsifizierbar sein (not falsifiable — Popper''s language), sich gegen X absichern (to hedge against X — strategic).","examples":[{"sentence":"Ideologien sind oft gegen empirische Widerlegung immunisiert.","translation":"Ideologies are often immunised against empirical refutation."},{"sentence":"Das System ist gegen externe Kritik immunisiert.","translation":"The system is immunised against external criticism."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Falsifizierbarkeit'' means?","options":["falsifiability","testability","refutability","disprovability"],"correctAnswer":"falsifiability"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Conspiracy theories are not a simple consequence of lack of education, but a complex epistemic phenomenon: they offer explanations for contingency and chaos, enable social belonging in communities of distrust, and are immunised against refutation — because every counterevidence counts as proof of the conspiracy. This epistemic immunisation makes them particularly resistant to enlightenment strategies.","options":["Verschwörungstheorien sind keine schlichte Folge mangelnder Bildung, sondern ein komplexes epistemisches Phänomen: Sie bieten Erklärungen für Kontingenz und Chaos, ermöglichen soziale Zugehörigkeit in Misstrauensgemeinschaften und sind gegen Widerlegung immunisiert — weil jeder Gegenbeleg als Beweis des Komplotts gilt. Diese epistemische Immunisierung macht sie besonders resistent gegenüber Aufklärungsstrategien.","Verschwörungstheorien sind immunisiert, weil Gegenbeweise als Beweis des Komplotts gelten.","Verschwörungstheorien bieten Erklärungen für Chaos und schaffen Gemeinschaft.","Mehr Bildung allein löst das Problem der Verschwörungstheorien nicht."],"correctAnswer":"Verschwörungstheorien sind keine schlichte Folge mangelnder Bildung, sondern ein komplexes epistemisches Phänomen: Sie bieten Erklärungen für Kontingenz und Chaos, ermöglichen soziale Zugehörigkeit in Misstrauensgemeinschaften und sind gegen Widerlegung immunisiert — weil jeder Gegenbeleg als Beweis des Komplotts gilt. Diese epistemische Immunisierung macht sie besonders resistent gegenüber Aufklärungsstrategien."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ideologien sind oft gegen empirische Widerlegung ___.","options":["immunisiert","geschützt","resistent","gesichert"],"correctAnswer":"immunisiert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The system is immunised against external criticism","wordBankItems":["Das","System","ist","gegen","externe","Kritik","immunisiert","."],"correctAnswer":"Das System ist gegen externe Kritik immunisiert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Kontingenz'' means?","options":["contingency","chance","unpredictability","randomness"],"correctAnswer":"contingency"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002eb',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss innovation ecosystems at B2","Use Innovationsökosystem vocabulary","Talk about Germany''s startup culture, innovation clusters, and R&D investment"],"explanation":{"intro":"Innovation ecosystem vocabulary covers Germany''s startup landscape, R&D investment, and innovation policy at B2.","culturalNote":"Innovationsökosystem: Germany: R&D spend: 3.1% GDP (2021) — above 3% target (EU Lisbon goal). Key: Mittelstand (SMEs — Weltmarktführer — hidden champions — Simon 2009 — 1,307 German hidden champions — B2B, specialised, global, low profile). Key companies: Siemens, Bosch, BASF (innovation powerhouses). Startup scene: Berlin (Zalando, Delivery Hero, HelloFresh — Unicorns). Munich. Hamburg. Key gap vs. USA: lack of DeepTech startups, Risikokapital (venture capital — German VC market 20× smaller than USA proportionally). Transfer problem: German universities produce research — but commercialisation is weak. Fraunhofer model: contract research — bridges gap. Key: Industrie 4.0 (digitalisation of manufacturing — Germany coined term 2011). SPACs. Technologietransfer. Die Digitalisierungslücke (Germany''s digitalisation gap — still relies on fax machines — e-government weak). Digital Hubs (government initiative)."},"examples":[{"german":"Deutschlands Innovationssystem ist stark in inkrementeller und schwach in disruptiver Innovation: Der Mittelstand exzelliert in graduellen Verbesserungen etablierter Technologien — eine Stärke, die für Industrie 4.0 und Hochpräzisionsfertigungen geeignet ist, aber das Ökosystem schlecht auf radikale Plattformtransformationen vorbereitet, die USA und China dominieren.","english":"Germany''s innovation system is strong in incremental and weak in disruptive innovation: the Mittelstand excels in gradual improvements of established technologies — a strength suitable for Industrie 4.0 and high-precision manufacturing, but poorly prepares the ecosystem for the radical platform transformations that the USA and China dominate."},{"german":"Innovationsökosysteme wachsen nicht durch staatliche Planung allein: Sie entstehen durch das Zusammenwirken von Kapitalverfügbarkeit, Talentkonzentration, akademischen Ankern, Netzwerkdichte und einer Risikokultur, die Scheitern als Lernprozess, nicht als Stigma begreift — eine Kultur, die Silicon Valley geprägt hat und die in Deutschland erst teilweise etabliert ist.","english":"Innovation ecosystems do not grow through state planning alone: they emerge through the interaction of capital availability, talent concentration, academic anchors, network density, and a risk culture that understands failure as a learning process, not a stigma — a culture that has shaped Silicon Valley and that is only partially established in Germany."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s hidden champions, innovation gaps, and risk culture at B2."}}',
'{"items":[{"word":"inkrementell","translation":"incremental","pronunciation":"in-kreh-men-TEL","example":"Inkrementelle Innovation."},{"word":"disruptiv","translation":"disruptive","pronunciation":"dis-roop-TEEF","example":"Disruptive Innovation."},{"word":"das Scheitern","translation":"failure","pronunciation":"dahs SHY-tern","example":"Scheitern als Lernprozess."},{"word":"das Stigma","translation":"stigma","pronunciation":"dahs SHTIG-ma","example":"Scheitern als Stigma."},{"word":"graduell","translation":"gradual","pronunciation":"gra-doo-EL","example":"Graduelle Verbesserungen."},{"word":"die Risikokultur","translation":"risk culture","pronunciation":"dee ri-ZEE-ko-kool-toor","example":"Risikokultur entwickeln."}]}',
'{"title":"X gut auf Y vorbereiten vs. X schlecht auf Y vorbereiten — to prepare X well/poorly for Y","pattern":"X gut/schlecht auf Y vorbereiten = to prepare X well/poorly for Y (vorbereiten auf + accusative — marks readiness for a future challenge; gut/schlecht = well/poorly — evaluates the degree of preparation)","explanation":"Vorbereiten auf = to prepare for (vorbereiten — separable: bereitet...vor; auf + accusative marks what is being prepared for). X gut auf Y vorbereitet = X well prepared for Y; X schlecht auf Y vorbereitet = X poorly prepared for Y. Das Ökosystem ist schlecht auf radikale Transformationen vorbereitet = The ecosystem is poorly prepared for radical transformations. Passive/predicative: X ist gut/schlecht vorbereitet auf Y (predicative — is prepared for). Active: X bereitet Y gut auf Z vor (transitive — X prepares Y for Z). Compare: gerüstet sein für (to be equipped for — similar), gewappnet sein gegen (to be armed against — more defensive), ausgerichtet sein auf (to be aligned for — more intentional design).","examples":[{"sentence":"Das Bildungssystem ist schlecht auf die Anforderungen der digitalen Wirtschaft vorbereitet.","translation":"The education system is poorly prepared for the demands of the digital economy."},{"sentence":"Diese Ausbildung bereitet Studierende gut auf die Berufspraxis vor.","translation":"This training prepares students well for professional practice."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Inkrementell'' means?","options":["incremental","gradual","step-by-step","cumulative"],"correctAnswer":"incremental"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Innovation ecosystems do not grow through state planning alone: they emerge through the interaction of capital availability, talent concentration, academic anchors, network density, and a risk culture that understands failure as a learning process, not a stigma — a culture that has shaped Silicon Valley and that is only partially established in Germany.","options":["Innovationsökosysteme wachsen nicht durch staatliche Planung allein: Sie entstehen durch das Zusammenwirken von Kapitalverfügbarkeit, Talentkonzentration, akademischen Ankern, Netzwerkdichte und einer Risikokultur, die Scheitern als Lernprozess, nicht als Stigma begreift — eine Kultur, die Silicon Valley geprägt hat und die in Deutschland erst teilweise etabliert ist.","Innovationsökosysteme brauchen mehr als staatliche Förderprogramme.","Eine Risikokultur, die Scheitern akzeptiert, ist Voraussetzung für disruptive Innovation.","Silicon-Valley-Dynamik braucht Kapital, Talent und die richtige Fehlerkultur."],"correctAnswer":"Innovationsökosysteme wachsen nicht durch staatliche Planung allein: Sie entstehen durch das Zusammenwirken von Kapitalverfügbarkeit, Talentkonzentration, akademischen Ankern, Netzwerkdichte und einer Risikokultur, die Scheitern als Lernprozess, nicht als Stigma begreift — eine Kultur, die Silicon Valley geprägt hat und die in Deutschland erst teilweise etabliert ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Bildungssystem ist schlecht auf die Anforderungen der digitalen Wirtschaft ___.","options":["vorbereitet","gerüstet","ausgerichtet","eingestellt"],"correctAnswer":"vorbereitet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This training prepares students well for professional practice","wordBankItems":["Diese","Ausbildung","bereitet","Studierende","gut","auf","die","Berufspraxis","vor","."],"correctAnswer":"Diese Ausbildung bereitet Studierende gut auf die Berufspraxis vor ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Disruptiv'' means?","options":["disruptive","radical","transformative","game-changing"],"correctAnswer":"disruptive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ec',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss patents and knowledge rights at B2","Use Patente und Wissensrecht vocabulary","Talk about intellectual property, patent system, and the knowledge commons debate"],"explanation":{"intro":"Patents and knowledge rights vocabulary covers intellectual property, the patent system critique, and open access debates at B2.","culturalNote":"Patente und Wissensrecht: Germany: Deutsches Patent- und Markenamt (DPMA — Munich). European Patent Office (EPO — Munich — world''s largest patent registry). Key: Germany #3 in European patent applications. Patent (20-year exclusivity on inventions — technical solutions). Urheberrecht (copyright — 70 years after death). Marke (trademark). Geschäftsgeheimnis (trade secret). Key debates: Software patents (controversial in EU — still restricted). Gene patents (Myriad Genetics vs. BRCA gene — 2013 US Supreme Court). Pharmaceutical patents vs. access to medicines (TRIPS, TRIPS waiver COVID vaccines). Open source (Richard Stallman — GNU — copyleft). Creative Commons. Knowledge commons (Wissensallmende). Key tension: Patent monopoly as incentive for innovation vs. knowledge as public good. Piracy and enforcement."},"examples":[{"german":"Das Patentsystem verkörpert einen pragmatischen Kompromiss zwischen zwei konkurrierenden gesellschaftlichen Interessen: Die zeitlich begrenzte Monopolgewährung schafft Anreize für kostspielige Forschungs- und Entwicklungsinvestitionen, während die Offenlegungspflicht dafür sorgt, dass das Wissen nach Ablauf des Patentschutzes der Allgemeinheit zugute kommt — ein Tauschgeschäft, das unter Druck gerät, wenn die Monopollaufzeit durch evergreening-Strategien verlängert wird.","english":"The patent system embodies a pragmatic compromise between two competing social interests: the temporally limited grant of monopoly creates incentives for costly research and development investments, while the disclosure obligation ensures that the knowledge benefits the public after expiry of patent protection — a trade-off that comes under pressure when the monopoly period is extended through evergreening strategies."},{"german":"Wissensrechte sind nicht neutral verteilt: In der globalen Wissensökonomie begünstigen Patentsysteme Länder und Unternehmen mit hoher F&E-Kapazität und rechtlicher Durchsetzungsmacht — und benachteiligen Entwicklungsländer, die auf Technologietransfer angewiesen sind. Die TRIPS-Vereinbarung der WTO hat geistiges Eigentum globalisiert, aber die Asymmetrie zwischen Wissenserzeugern und Wissensnehmern nicht verringert.","english":"Knowledge rights are not neutrally distributed: in the global knowledge economy, patent systems favour countries and companies with high R&D capacity and legal enforcement power — and disadvantage developing countries dependent on technology transfer. The WTO TRIPS agreement has globalised intellectual property, but has not reduced the asymmetry between knowledge producers and knowledge receivers."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the patent system, evergreening, and knowledge rights asymmetry at B2."}}',
'{"items":[{"word":"die Monopolgewährung","translation":"grant of monopoly","pronunciation":"dee mo-no-POHL-geh-vä-roong","example":"Temporäre Monopolgewährung."},{"word":"die Offenlegungspflicht","translation":"disclosure obligation","pronunciation":"dee OF-en-leh-goongs-pfllikht","example":"Offenlegungspflicht des Patents."},{"word":"das Tauschgeschäft","translation":"trade-off","pronunciation":"dahs TOWSH-geh-sheft","example":"Pragmatisches Tauschgeschäft."},{"word":"evergreening","translation":"evergreening","pronunciation":"EV-er-green-ing","example":"Evergreening-Strategien."},{"word":"begünstigen","translation":"to favour","pronunciation":"beh-GÜN-sti-gen","example":"Patentsysteme begünstigen."},{"word":"die Asymmetrie","translation":"asymmetry","pronunciation":"dee ah-zü-meh-TREE","example":"Globale Asymmetrie."}]}',
'{"title":"Das Tauschgeschäft gerät unter Druck wenn X — the trade-off comes under pressure when X","pattern":"ein Tauschgeschäft/Kompromiss gerät unter Druck, wenn X = a trade-off/compromise comes under pressure when X (unter Druck geraten = to come under pressure — idiomatic; Tauschgeschäft = trade-off, quid pro quo — marks a conditional erosion of the original balance)","explanation":"Unter Druck geraten = to come under pressure (geraten = to get into — a stative/process verb: geraten unter Druck — come under pressure; the phrase marks escalation or threat to an established equilibrium). Ein Tauschgeschäft gerät unter Druck, wenn X = a trade-off comes under pressure when X. The phrase shows that the balance of a compromise (here: patent system = monopoly in exchange for disclosure) is being eroded by a particular practice or development. Compare: in Frage gestellt werden (to be called into question — more static), bedroht werden durch (to be threatened by — more active), kippen (to tip, topple — more colloquial/abrupt), ins Wanken geraten (to start to totter — more dramatic).","examples":[{"sentence":"Das Tauschgeschäft gerät unter Druck, wenn eine Seite nicht einhält, was sie versprochen hat.","translation":"The trade-off comes under pressure when one side does not keep what it promised."},{"sentence":"Der Kompromiss gerät unter Druck, wenn neue Akteure nicht in ihn eingebunden sind.","translation":"The compromise comes under pressure when new actors are not included in it."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Begünstigen'' means?","options":["to favour","to advantage","to benefit","to privilege"],"correctAnswer":"to favour"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The patent system embodies a pragmatic compromise between two competing social interests: the temporally limited grant of monopoly creates incentives for costly research and development investments, while the disclosure obligation ensures that the knowledge benefits the public after expiry of patent protection — a trade-off that comes under pressure when the monopoly period is extended through evergreening strategies.","options":["Das Patentsystem verkörpert einen pragmatischen Kompromiss zwischen zwei konkurrierenden gesellschaftlichen Interessen: Die zeitlich begrenzte Monopolgewährung schafft Anreize für kostspielige Forschungs- und Entwicklungsinvestitionen, während die Offenlegungspflicht dafür sorgt, dass das Wissen nach Ablauf des Patentschutzes der Allgemeinheit zugute kommt — ein Tauschgeschäft, das unter Druck gerät, wenn die Monopollaufzeit durch evergreening-Strategien verlängert wird.","Patente sind ein Kompromiss: Monopol gegen Wissensoffenlegung.","Evergreening verlängert Patentlaufzeiten und untergräbt den Kern des Patentsystems.","Das Patentsystem schafft Anreize für Innovation auf Kosten des öffentlichen Zugangs zu Wissen."],"correctAnswer":"Das Patentsystem verkörpert einen pragmatischen Kompromiss zwischen zwei konkurrierenden gesellschaftlichen Interessen: Die zeitlich begrenzte Monopolgewährung schafft Anreize für kostspielige Forschungs- und Entwicklungsinvestitionen, während die Offenlegungspflicht dafür sorgt, dass das Wissen nach Ablauf des Patentschutzes der Allgemeinheit zugute kommt — ein Tauschgeschäft, das unter Druck gerät, wenn die Monopollaufzeit durch evergreening-Strategien verlängert wird."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Tauschgeschäft gerät unter Druck, wenn eine Seite nicht einhält, was sie ___ hat.","options":["versprochen","vereinbart","zugesagt","garantiert"],"correctAnswer":"versprochen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The compromise comes under pressure when new actors are not included in it","wordBankItems":["Der","Kompromiss","gerät","unter","Druck",",","wenn","neue","Akteure","nicht","in","ihn","eingebunden","sind","."],"correctAnswer":"Der Kompromiss gerät unter Druck , wenn neue Akteure nicht in ihn eingebunden sind ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Asymmetrie'' means?","options":["asymmetry","imbalance","disparity","inequality"],"correctAnswer":"asymmetry"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ed',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Open Science and data availability at B2","Use Open Science und Datenverfügbarkeit vocabulary","Talk about open access, research data management, and Germany''s Open Science policies"],"explanation":{"intro":"Open Science and data availability vocabulary covers open access publishing, research data management, and Germany''s Open Science policies at B2.","culturalNote":"Open Science und Datenverfügbarkeit: Key: Open Access (frei zugängliche Wissenschaft — Plan S 2018 — European Research Council mandate — all ERC-funded research must be open access). Germany: Allianz der deutschen Wissenschaftsorganisationen (collective licensing DEAL agreement with Wiley, Springer Nature — open access + read). FAIR principles (Findable, Accessible, Interoperable, Reusable — for research data). Research data management (Forschungsdatenmanagement — NFDI — Nationale Forschungsdateninfrastruktur — German initiative). Key debate: Green OA (self-archiving) vs. Gold OA (publisher charges APCs — article processing charges). Preprint servers (arXiv, bioRxiv, medRxiv — COVID sped up). Open peer review. Open code (reproducibility). Key tension: commercial publishers (Elsevier, Springer Nature) vs. academic community. Sci-Hub controversy (Alexandra Elbakyan — pirate science access)."},"examples":[{"german":"Open Science ist mehr als kostenloser Lesezugang: Das volle Programm umfasst Open Access für Publikationen, FAIR-konforme Forschungsdaten, Open-Source-Code, Open Peer Review und Open Educational Resources — eine Transformation der Wissenschaftsinfrastruktur, die die traditionellen Geschäftsmodelle kommerzieller Verlage grundlegend herausfordert und eine kollektive Koordinationsleistung der Wissenschaftsinstitutionen erfordert.","english":"Open Science is more than free reading access: the full programme includes open access for publications, FAIR-compliant research data, open-source code, open peer review, and open educational resources — a transformation of scientific infrastructure that fundamentally challenges the traditional business models of commercial publishers and requires a collective coordination achievement of scientific institutions."},{"german":"Das Öffentlichkeitsprinzip der Wissenschaft — dass Erkenntnisse der Allgemeinheit zugute kommen sollen — kollidiert mit dem Geschäftsmodell kommerzieller Wissenschaftsverlage, die öffentlich finanzierte Forschung kostenpflichtig hinter Paywalls veröffentlichen und dabei Renditen erzielen, die andere Branchen selten erreichen. Die Open-Access-Bewegung artikuliert diesen Widerspruch und fordert eine Neuordnung des wissenschaftlichen Publikationssystems.","english":"The public interest principle of science — that findings should benefit the public — collides with the business model of commercial academic publishers, who publish publicly funded research behind paid paywalls and in doing so achieve returns that other sectors rarely reach. The open access movement articulates this contradiction and demands a reorganisation of the scientific publication system."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Open Science, FAIR principles, and the commercial publisher debate at B2."}}',
'{"items":[{"word":"der Lesezugang","translation":"reading access","pronunciation":"dayr LAY-zeh-tsoo-gank","example":"Kostenloser Lesezugang."},{"word":"die Koordinationsleistung","translation":"coordination achievement","pronunciation":"dee ko-or-di-NAH-tsyohns-lys-toong","example":"Kollektive Koordinationsleistung."},{"word":"das Öffentlichkeitsprinzip","translation":"public interest principle","pronunciation":"dahs EF-ent-likh-kyts-prin-tsip","example":"Öffentlichkeitsprinzip der Wissenschaft."},{"word":"kostenpflichtig","translation":"fee-based/paid","pronunciation":"KOS-ten-pflikh-tikh","example":"Kostenpflichtig veröffentlichen."},{"word":"die Paywall","translation":"paywall","pronunciation":"dee PAY-vahl","example":"Hinter Paywalls."},{"word":"artikulieren","translation":"to articulate","pronunciation":"ar-ti-koo-LEE-ren","example":"Widerspruch artikulieren."}]}',
'{"title":"X kollisiert mit Y — X collides with Y (structural conflict between incompatible logics)","pattern":"X kollidiert mit Y = X collides with Y (kollidieren mit + dative — marks a direct, structural conflict between two logics or principles that cannot both be fully satisfied simultaneously)","explanation":"Kollidieren mit = to collide with (kollidieren — cognate of collide; mit + dative = with Y). Das Öffentlichkeitsprinzip der Wissenschaft kollidiert mit dem Geschäftsmodell kommerzieller Verlage = the public interest principle of science collides with the business model of commercial publishers. The phrase marks a stronger conflict than ''tension'': the two things cannot fully coexist — one must give way. Compare: in Spannung stehen zu (to stand in tension — both coexist but pull apart), im Widerspruch stehen zu (to contradict — logical incompatibility), unvereinbar sein mit (to be incompatible with — cannot coexist at all), stören (to disturb — weaker, one affects the other without full confrontation).","examples":[{"sentence":"Das Ziel der Gewinnmaximierung kollidiert mit dem Ziel der Nachhaltigkeit.","translation":"The goal of profit maximisation collides with the goal of sustainability."},{"sentence":"Sicherheitsinteressen kollidieren mit dem Recht auf Privatsphäre.","translation":"Security interests collide with the right to privacy."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Kostenpflichtig'' means?","options":["fee-based/paid","chargeable","subject to fees","not free"],"correctAnswer":"fee-based/paid"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Open Science is more than free reading access: the full programme includes open access for publications, FAIR-compliant research data, open-source code, open peer review, and open educational resources — a transformation of scientific infrastructure that fundamentally challenges the traditional business models of commercial publishers and requires a collective coordination achievement of scientific institutions.","options":["Open Science ist mehr als kostenloser Lesezugang: Das volle Programm umfasst Open Access für Publikationen, FAIR-konforme Forschungsdaten, Open-Source-Code, Open Peer Review und Open Educational Resources — eine Transformation der Wissenschaftsinfrastruktur, die die traditionellen Geschäftsmodelle kommerzieller Verlage grundlegend herausfordert und eine kollektive Koordinationsleistung der Wissenschaftsinstitutionen erfordert.","Open Science fordert freien Zugang zu wissenschaftlichen Publikationen und Daten.","Das volle Open-Science-Programm geht weit über Open Access hinaus.","Kommerzielle Verlage blockieren eine umfassende Open-Science-Transformation."],"correctAnswer":"Open Science ist mehr als kostenloser Lesezugang: Das volle Programm umfasst Open Access für Publikationen, FAIR-konforme Forschungsdaten, Open-Source-Code, Open Peer Review und Open Educational Resources — eine Transformation der Wissenschaftsinfrastruktur, die die traditionellen Geschäftsmodelle kommerzieller Verlage grundlegend herausfordert und eine kollektive Koordinationsleistung der Wissenschaftsinstitutionen erfordert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Ziel der Gewinnmaximierung kollidiert mit dem Ziel der ___.","options":["Nachhaltigkeit","Umwelt","Ökologie","Klimapolitik"],"correctAnswer":"Nachhaltigkeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Security interests collide with the right to privacy","wordBankItems":["Sicherheitsinteressen","kollidieren","mit","dem","Recht","auf","Privatsphäre","."],"correctAnswer":"Sicherheitsinteressen kollidieren mit dem Recht auf Privatsphäre ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Artikulieren'' means?","options":["to articulate","to express","to formulate","to voice"],"correctAnswer":"to articulate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ee',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss technology assessment at B2","Use Technologiefolgenabschätzung vocabulary","Talk about Germany''s TA Institute, precautionary principle, and anticipatory governance"],"explanation":{"intro":"Technology assessment vocabulary covers precautionary principle, anticipatory governance, and Germany''s TA tradition at B2.","culturalNote":"Technologiefolgenabschätzung (TA): Germany: Büro für Technikfolgen-Abschätzung beim Deutschen Bundestag (TAB — 1990 — parliamentary TA office — advises German parliament on technology risks and opportunities). Key: Vorsorgerinzip (precautionary principle — EU principle — if activity risks harm to humans/environment, precautionary measures shall be taken even if uncertain — Maastricht Treaty). Risikogesellschaft (risk society — Ulrich Beck 1986 — modernity creates new risks uncontrollable by classic institutions). Nuclear power (Kernkraft — Germany Atomausstieg 2023 — last 3 reactors closed — Fukushima reaction). CCS (Carbon Capture and Storage — moratorium in Germany). CRISPR governance. Technikfolgenabschätzung: assesses downstream consequences before deployment. Key: anticipatory governance (vorausschauende Steuerung). Collingridge dilemma (early = flexible but low information; late = high info but locked in)."},"examples":[{"german":"Das Vorsorgeprinzip operationalisiert ethische Ungewissheit: Wenn die Folgen einer Technologie unbekannt oder unzureichend erforscht sind, rechtfertigt das Fehlen wissenschaftlicher Gewissheit keine Untätigkeit — der Maßstab ist nicht Beweisbarkeit des Schadens, sondern Plausibilität des Risikos. Diese Umkehrung der Beweislast unterscheidet das Vorsorgeprinzip von reaktivem Schadensbegrenzungsrecht.","english":"The precautionary principle operationalises ethical uncertainty: when the consequences of a technology are unknown or insufficiently researched, the absence of scientific certainty does not justify inaction — the standard is not provability of harm, but plausibility of risk. This reversal of the burden of proof distinguishes the precautionary principle from reactive damage limitation law."},{"german":"Das Collingridge-Dilemma beschreibt eine strukturelle Spannung in der Technologiesteuerung: Im frühen Stadium ist die Technologie formbar, aber die Wissensgrundlage für Regulierungsentscheidungen dünn; im späten Stadium ist das Wissen vorhanden, aber die Technologie so tief in gesellschaftliche Infrastrukturen eingebettet, dass Korrekturen prohibitiv kostspielig sind. Technologiefolgenabschätzung versucht, diese Spannung durch frühzeitige Szenarienanalyse zu mildern.","english":"The Collingridge dilemma describes a structural tension in technology governance: in the early stage, the technology is malleable, but the knowledge base for regulatory decisions is thin; in the late stage, knowledge is available, but the technology is so deeply embedded in societal infrastructures that corrections are prohibitively costly. Technology assessment tries to mitigate this tension through early scenario analysis."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the precautionary principle, Collingridge dilemma, and technology assessment at B2."}}',
'{"items":[{"word":"das Vorsorgeprinzip","translation":"precautionary principle","pronunciation":"dahs FOR-zor-geh-prin-tsip","example":"Europäisches Vorsorgeprinzip."},{"word":"operationalisieren","translation":"to operationalise","pronunciation":"o-peh-ra-tsyoh-na-li-ZEE-ren","example":"Prinzip operationalisieren."},{"word":"die Beweislast","translation":"burden of proof","pronunciation":"dee beh-VYS-last","example":"Umkehrung der Beweislast."},{"word":"formbar","translation":"malleable","pronunciation":"FORM-bar","example":"Formbare Technologie."},{"word":"prohibitiv","translation":"prohibitively","pronunciation":"pro-hi-bi-TEEF","example":"Prohibitiv kostspielig."},{"word":"die Szenarienanalyse","translation":"scenario analysis","pronunciation":"dee stse-NAH-ryeh-an-ah-lü-zeh","example":"Frühzeitige Szenarienanalyse."}]}',
'{"title":"X so tief in Y eingebettet, dass Z prohibitiv kostspielig ist — X so deeply embedded in Y that Z is prohibitively costly","pattern":"X ist so tief in Y eingebettet, dass Z (prohibitiv) kostspielig/unmöglich ist = X is so deeply embedded in Y that Z is (prohibitively) costly/impossible (so...dass = so...that — consecutive clause expressing result; eingebettet = embedded — past participle used as predicate; tief = deeply)","explanation":"Eingebettet in = embedded in (einbetten — to embed; eingebettet = embedded). So...dass = so...that (consecutive/result clause: the degree (so) leads to a consequence (dass + result)). X ist so tief in Y eingebettet, dass Z prohibitiv kostspielig ist = X is so deeply embedded in Y that Z is prohibitively costly. The pattern expresses lock-in: the technology (X) has become so integral to infrastructure/society (Y) that changing it (Z) would cost too much. Widely used in path dependency arguments, institutional economics, and technology governance. Compare: fest verankert in (firmly anchored in — more positive), tief verwurzelt in (deeply rooted in — more organic/cultural), kaum noch umkehrbar (barely reversible — emphasises irreversibility).","examples":[{"sentence":"Fossile Energie ist so tief in die Infrastruktur eingebettet, dass ein schneller Ausstieg prohibitiv teuer wäre.","translation":"Fossil energy is so deeply embedded in the infrastructure that a rapid exit would be prohibitively expensive."},{"sentence":"Das System ist so tief in bürokratische Strukturen eingebettet, dass eine Reform scheitert.","translation":"The system is so deeply embedded in bureaucratic structures that a reform fails."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Formbar'' means?","options":["malleable","flexible","adaptable","changeable"],"correctAnswer":"malleable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The precautionary principle operationalises ethical uncertainty: when the consequences of a technology are unknown or insufficiently researched, the absence of scientific certainty does not justify inaction — the standard is not provability of harm, but plausibility of risk. This reversal of the burden of proof distinguishes the precautionary principle from reactive damage limitation law.","options":["Das Vorsorgeprinzip operationalisiert ethische Ungewissheit: Wenn die Folgen einer Technologie unbekannt oder unzureichend erforscht sind, rechtfertigt das Fehlen wissenschaftlicher Gewissheit keine Untätigkeit — der Maßstab ist nicht Beweisbarkeit des Schadens, sondern Plausibilität des Risikos. Diese Umkehrung der Beweislast unterscheidet das Vorsorgeprinzip von reaktivem Schadensbegrenzungsrecht.","Das Vorsorgeprinzip sagt: Zweifel an Sicherheit reicht nicht, man braucht Beweise für den Schaden.","Das Vorsorgeprinzip kehrt die Beweislast um: Nicht der Staat muss den Schaden beweisen.","Wenn Risiken plausibel sind, darf wissenschaftliche Unsicherheit keine Untätigkeit begründen."],"correctAnswer":"Das Vorsorgeprinzip operationalisiert ethische Ungewissheit: Wenn die Folgen einer Technologie unbekannt oder unzureichend erforscht sind, rechtfertigt das Fehlen wissenschaftlicher Gewissheit keine Untätigkeit — der Maßstab ist nicht Beweisbarkeit des Schadens, sondern Plausibilität des Risikos. Diese Umkehrung der Beweislast unterscheidet das Vorsorgeprinzip von reaktivem Schadensbegrenzungsrecht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Fossile Energie ist so tief in die Infrastruktur eingebettet, dass ein schneller Ausstieg prohibitiv ___ wäre.","options":["teuer","kostspielig","aufwendig","riskant"],"correctAnswer":"teuer"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The system is so deeply embedded in bureaucratic structures that a reform fails","wordBankItems":["Das","System","ist","so","tief","in","bürokratische","Strukturen","eingebettet",",","dass","eine","Reform","scheitert","."],"correctAnswer":"Das System ist so tief in bürokratische Strukturen eingebettet , dass eine Reform scheitert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Prohibitiv'' means?","options":["prohibitively","excessively","impossibly","extremely"],"correctAnswer":"prohibitively"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

